const advancedDebugTab = {
    _setSafeContent(el, html) {
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');
        const frag = document.createDocumentFragment();
        Array.from(doc.body.childNodes).forEach(n => frag.appendChild(n));
        el.replaceChildren(frag);
    },

    init() {
        const pane = document.getElementById('advanced-debug');
        if (!pane) return;
        this._setSafeContent(pane, this.renderBase());
        this.bind();

        $('#advanced-debug-tab').on('shown.bs.tab', () => this.checkStatus());
        if ($('#advanced-debug').hasClass('active') || $('#advanced-debug').hasClass('show')) {
            this.checkStatus();
        }
    },

    renderBase() {
        return `
            <h3>Advanced Debug Recorder</h3>
            <p>Capture a deep, AI-friendly debugging timeline from a running offline app: user interactions, console output, errors, network calls, storage/history changes, DOM mutations, state snapshots, and instrumented callback inputs/outputs.</p>

            <div class="integration-section mb-4" id="advanced-debug-integration-panel">
                <h4>Integration</h4>
                <div id="advanced-debug-status" class="d-flex align-items-center p-3 rounded"
                    style="background-color: #343a40; border: 1px solid #495057;">
                    <span class="status-badge mr-3" id="advanced-debug-status-badge">Checking...</span>
                    <span id="advanced-debug-status-message" class="flex-grow-1">Checking if advanceddebug.js is integrated...</span>
                    <button id="advanced-debug-refresh-status-btn" class="btn btn-sm btn-outline-secondary ml-2">Refresh</button>
                </div>
                <div class="actions-section mt-3">
                    <button id="advanced-debug-copy-btn" class="btn btn-info">Copy advanceddebug.js Code</button>
                    <button id="advanced-debug-add-btn" class="btn btn-success" disabled>Add advanceddebug.js to Project</button>
                    <button id="advanced-debug-update-btn" class="btn btn-warning" style="display:none;">Update advanceddebug.js</button>
                    <div id="advanced-debug-progress" class="progress-indicator" aria-live="polite" style="display:none;">
                        <span class="spinner" aria-hidden="true"></span>
                        <span id="advanced-debug-progress-text">Preparing integration...</span>
                    </div>
                </div>
                <div class="mt-3 small" style="line-height:1.35;">
                    Add this script near the top of each page. Open your app and press <kbd>Ctrl/Cmd + Alt + D</kbd> to copy or download the captured AI context file.
                </div>
            </div>

            <hr class="my-4">

            <div class="ai-prompt-section">
                <h4>Optional App Instrumentation</h4>
                <p class="text-muted">The recorder automatically wraps event listeners and timers loaded after it. For direct business-logic functions or app state, add explicit hooks like these.</p>
                <div class="position-relative">
                    <textarea id="advanced-debug-sample" class="form-control" rows="12" readonly style="font-family: monospace; font-size: 0.85em;">
// Capture custom app state in every snapshot.
AdvancedDebug.registerStateProvider('appState', () => window.appState);

// Wrap a function to record arguments, return values, thrown errors, and promise results.
saveRecord = AdvancedDebug.trackFunction('saveRecord', saveRecord);

// Wrap all methods on a plain object.
AdvancedDebug.wrapObject(window.apiClient, 'apiClient');

// Add custom breadcrumbs anywhere.
AdvancedDebug.record('domain.step', { screen: 'checkout', id: currentId });
                    </textarea>
                    <button id="advanced-debug-copy-sample-btn" class="btn btn-sm btn-light position-absolute" style="top: 10px; right: 10px;">Copy</button>
                </div>
            </div>
        `;
    },

    bind() {
        $('#advanced-debug-refresh-status-btn').on('click', () => this.checkStatus());
        $('#advanced-debug-copy-btn').on('click', () => this.copyAdvancedDebugCode());
        $('#advanced-debug-add-btn').on('click', () => this.integrate(false));
        $('#advanced-debug-update-btn').on('click', () => this.integrate(true));
        $('#advanced-debug-copy-sample-btn').on('click', () => {
            const text = document.getElementById('advanced-debug-sample').value;
            if (!text) return;
            navigator.clipboard.writeText(text);
            const btn = $('#advanced-debug-copy-sample-btn');
            const orig = btn.text();
            btn.text('Copied');
            setTimeout(() => btn.text(orig), 1500);
        });
    },

    async checkStatus() {
        const statusBadge = $('#advanced-debug-status-badge');
        const statusMessage = $('#advanced-debug-status-message');
        const addBtn = $('#advanced-debug-add-btn');
        const updateBtn = $('#advanced-debug-update-btn');

        addBtn.prop('disabled', true).show();
        updateBtn.hide();
        statusBadge.text('Checking...').attr('class', 'status-badge checking');
        statusMessage.text('Checking if advanceddebug.js is integrated...');

        if (!loadFolder || !loadFolder.fileHandle) {
            statusBadge.text('No Project').attr('class', 'status-badge not-found');
            statusMessage.text('Load a directory first to check integration.');
            return;
        }

        const files = Array.isArray(loadFolder.fileStructure) ? loadFolder.fileStructure : [];
        const debugFile = files.find(f => f.name === 'advanceddebug.js');
        const htmlFiles = files.filter(f => f && f.kind === 'file' && /\.html?$/i.test(f.name || ''));

        if (debugFile) {
            statusBadge.text('Found').attr('class', 'status-badge found');
            addBtn.hide();
            updateBtn.show();
        } else {
            statusBadge.text('Not Found').attr('class', 'status-badge not-found');
            addBtn.prop('disabled', false).show();
            updateBtn.hide();
        }

        const tagStatus = await this._countHtmlScriptTags(htmlFiles);
        if (debugFile && tagStatus.withTag < tagStatus.total) {
            statusMessage.text('advanceddebug.js is present; ' + tagStatus.withTag + ' of ' + tagStatus.total + ' HTML files include it. Click Update to inject missing tags.');
        } else if (debugFile) {
            statusMessage.text('advanceddebug.js is present and script tags are integrated.');
        } else {
            statusMessage.text('advanceddebug.js is not yet integrated in your project.');
        }
    },

    async _countHtmlScriptTags(htmlFiles) {
        const result = { total: htmlFiles.length, withTag: 0 };
        for (const file of htmlFiles) {
            try {
                const content = await this._readFileContent(file);
                if (/advanceddebug\.js/i.test(content)) result.withTag += 1;
            } catch (err) {
                console.warn('AdvancedDebug: could not inspect HTML file', file.relativePath || file.name, err);
            }
        }
        return result;
    },
    getEmbeddedAdvancedDebugCode() {
        return decodeURIComponent(escape(atob('')));
    },


    async getAdvancedDebugCode() {
        try {
            const response = await fetch('advanceddebug.js', { cache: 'no-store' });
            if (!response.ok) throw new Error('HTTP ' + response.status);
            return await response.text();
        } catch (err) {
            console.warn('AdvancedDebug: failed to fetch local advanceddebug.js source; using embedded fallback copy.', err);
            return this.getEmbeddedAdvancedDebugCode();
        }
    },

    async copyAdvancedDebugCode() {
        try {
            const code = await this.getAdvancedDebugCode();
            await navigator.clipboard.writeText(code);
            const btn = $('#advanced-debug-copy-btn');
            const orig = btn.text();
            btn.text('Copied');
            setTimeout(() => btn.text(orig), 1500);
        } catch (err) {
            alert('Failed to copy advanceddebug.js: ' + err.message);
        }
    },

    async integrate(isUpdate) {
        if (!loadFolder || !loadFolder.fileHandle) {
            alert('Please load a directory first.');
            return;
        }
        if (isUpdate && !confirm('This will overwrite your existing advanceddebug.js file. Continue?')) {
            return;
        }

        const addBtn = $('#advanced-debug-add-btn');
        const updateBtn = $('#advanced-debug-update-btn');
        const progress = $('#advanced-debug-progress');
        const progressText = $('#advanced-debug-progress-text');
        const actionBtn = isUpdate ? updateBtn : addBtn;
        const otherBtn = isUpdate ? addBtn : updateBtn;
        const originalText = actionBtn.data('originalText') || actionBtn.text();
        actionBtn.data('originalText', originalText);

        actionBtn.prop('disabled', true).text('Working...');
        otherBtn.prop('disabled', true);
        progress.css('display', 'flex').removeClass('success error').addClass('loading');
        progressText.text(isUpdate ? 'Updating advanceddebug.js...' : 'Adding advanceddebug.js to your project...');

        try {
            const code = await this.getAdvancedDebugCode();
            await this._writeProjectFile('advanceddebug.js', code);
            const summary = await this._injectScriptTags();

            if (loadFolder.refreshFileTree && loadFolder.recursivelyReadDirectory) {
                loadFolder.fileStructure = await loadFolder.recursivelyReadDirectory([], loadFolder.fileHandle);
                loadFolder.refreshFileTree();
            }
            await this.checkStatus();

            progress.removeClass('loading error').addClass('success');
            progressText.text('advanceddebug.js integrated. Updated ' + summary.updated + ' HTML file(s).');
            setTimeout(() => {
                progress.css('display', 'none');
                progress.removeClass('success');
            }, 3500);

            actionBtn.prop('disabled', false).text('Done');
            setTimeout(() => actionBtn.prop('disabled', false).text(actionBtn.data('originalText') || originalText), 2200);
            otherBtn.prop('disabled', false);
        } catch (err) {
            console.error('AdvancedDebug integrate error:', err);
            progress.removeClass('loading success').addClass('error');
            progressText.text('Failed to integrate advanceddebug.js. See console.');
            setTimeout(() => {
                progress.css('display', 'none');
                progress.removeClass('error');
            }, 5000);
            actionBtn.prop('disabled', false).text(actionBtn.data('originalText') || originalText);
            otherBtn.prop('disabled', false);
            alert('Error: ' + err.message);
        } finally {
            progress.removeClass('loading');
        }
    },

    async _writeProjectFile(filename, content) {
        const fileHandle = await loadFolder.fileHandle.getFileHandle(filename, { create: true });
        const writable = await fileHandle.createWritable();
        try {
            await writable.write(content);
        } finally {
            await writable.close();
        }
    },

    async _injectScriptTags() {
        const result = { total: 0, updated: 0, alreadyPresent: 0, missingHead: 0, failures: [] };
        const files = Array.isArray(loadFolder.fileStructure) ? loadFolder.fileStructure : [];
        const htmlFiles = files.filter(f => f && f.kind === 'file' && /\.html?$/i.test(f.name || ''));
        result.total = htmlFiles.length;

        for (const file of htmlFiles) {
            try {
                const outcome = await this._injectScriptTag(file);
                if (outcome === 'updated') result.updated += 1;
                if (outcome === 'already-present') result.alreadyPresent += 1;
                if (outcome === 'missing-head') result.missingHead += 1;
            } catch (err) {
                result.failures.push({ path: file.relativePath || file.name, error: err.message });
                console.error('AdvancedDebug: failed to update HTML file:', file.relativePath || file.name, err);
            }
        }
        return result;
    },

    _findOpenEditorByRelativePath(relativePath) {
        if (typeof editor === 'undefined' || !editor || !editor._meta) return null;
        for (const [uuid, meta] of Object.entries(editor._meta)) {
            if (meta && meta.relativePath === relativePath) {
                return { uuid, meta, view: editor.instance ? editor.instance[uuid] : null };
            }
        }
        return null;
    },

    async _readFileContent(file) {
        const openInfo = this._findOpenEditorByRelativePath(file.relativePath);
        if (openInfo && openInfo.view) return openInfo.view.state.doc.toString();
        if (loadFolder.getFileContent) return await loadFolder.getFileContent(file);
        const blob = await file.entry.getFile();
        return await blob.text();
    },

    _computeRelativeScriptPath(relativePath) {
        const dir = relativePath && relativePath.includes('/') ? relativePath.substring(0, relativePath.lastIndexOf('/')) : '';
        if (!dir) return 'advanceddebug.js';
        const depth = dir.split('/').filter(Boolean).length;
        return '../'.repeat(depth) + 'advanceddebug.js';
    },

    async _writeHtmlFile(file, content) {
        let prepared = content;
        if (typeof editor !== 'undefined' && editor.ensureUnshippedBanner) {
            prepared = editor.ensureUnshippedBanner(prepared);
        }
        const writable = await file.entry.createWritable();
        try {
            await writable.write(prepared);
        } finally {
            await writable.close();
        }
        file.text = prepared;

        const openInfo = this._findOpenEditorByRelativePath(file.relativePath);
        if (openInfo && openInfo.view) {
            const current = openInfo.view.state.doc.toString();
            if (current !== prepared) {
                openInfo.view.dispatch({ changes: { from: 0, to: current.length, insert: prepared } });
            }
            if (openInfo.meta) openInfo.meta.text = prepared;
            if (editor.dirtyFiles) editor.dirtyFiles.delete(openInfo.uuid);
            if (typeof editor._setStatus === 'function') editor._setStatus(openInfo.uuid, 'Saved', 'saved');
        }
    },

    async _injectScriptTag(file) {
        const content = await this._readFileContent(file);
        if (/advanceddebug\.js/i.test(content)) return 'already-present';
        const headMatch = content.match(/(<head[^>]*>)/i);
        if (!headMatch) return 'missing-head';
        const scriptPath = this._computeRelativeScriptPath(file.relativePath || file.name);
        const tag = '\n    <\x73cript src="' + scriptPath + '"></script>';
        const next = content.replace(headMatch[0], headMatch[0] + tag);
        if (next === content) return 'already-present';
        await this._writeHtmlFile(file, next);
        return 'updated';
    }
};
